import React, { useState, useEffect } from "react";
import Swal from "sweetalert2";
import "bootstrap/dist/css/bootstrap.min.css";
import * as XLSX from "xlsx";
import config from "./config";

const App = () => {
  const [loaderVisible, setLoaderVisible] = useState(false);
  const [options, setOptions] = useState([]);
  //const [selectedOption, setSelectedOption] = useState("");
  const [fechaInicio, setFechaInicio] = useState("");
  const [fechaFin, setFechaFin] = useState("");


  const getUrlParams = () => {
    const params = new URLSearchParams(window.location.search);
    const id = params.get("id");
    const campana = params.get("campana");

    if (!id || !campana) {
      throw new Error("Faltan parámetros en la URL.");
    }

    return { id, campana };
  };

  const handleTokenError = () => {
    localStorage.removeItem("token");
    Swal.fire("Error", "No estás autenticado. Por favor, inicia sesión.", "error").then(() => {
      window.location.href = "/";
    });
  };

  const decrypt = async (value) => {
    if (!value || value.trim() === "") {
      throw new Error("El valor encriptado está vacío o es inválido.");
    }

    const token = localStorage.getItem("token");
    if (!token) {
      handleTokenError();
      return;
    }

    const response = await fetch(`${config.API_BASE_URL}/decrypt`, {
      method: "POST",
      headers: {
        "Content-Type": "application/json",
        Authorization: `Bearer ${token}`,
      },
      body: JSON.stringify({ encrypted_value: value }),
    });

    if (response.status === 401) {
      handleTokenError();
      return;
    }

    if (!response.ok) {
      const errorText = await response.text();
      throw new Error(`Error al desencriptar: ${errorText}`);
    }

    const data = await response.json();
    if (!data.decrypted_value) {
      throw new Error("La API no devolvió un valor desencriptado.");
    }

    return data.decrypted_value;
  };

  const fetchOptions = async () => {
    try {
      const token = localStorage.getItem("token");
      if (!token) {
        handleTokenError();
        return;
      }

      const urlParams = getUrlParams();
      const idCampana = await decrypt(urlParams.campana);

      const response = await fetch(`${config.API_BASE_URL}/drops`, {
        method: "POST",
        headers: {
          "Content-Type": "application/json",
          Authorization: `Bearer ${token}`,
        },
        body: JSON.stringify({ ddl: "GESTIONES_CAMPANA", id_campana: idCampana }),
      });

      if (!response.ok) {
        throw new Error(`Error al obtener opciones: ${response.statusText}`);
      }

      const data = await response.json();

      if (!Array.isArray(data)) {
        throw new Error("La API no devolvió un arreglo válido.");
      }

      setOptions(data);
    } catch (error) {
      Swal.fire("Error", `No se pudieron cargar las opciones: ${error.message}`, "error");
    }
  };

  useEffect(() => {
    fetchOptions();
  }, []);

  const handleDownloadTemplate = async () => {
    try {
      if (!fechaInicio || !fechaFin) {
        throw new Error("Debes seleccionar un rango de fechas antes de descargar.");
      }
  
      const token = localStorage.getItem("token");
      if (!token) {
        handleTokenError();
        return;
      }
  
      const response = await fetch(`${config.API_BASE_URL}/consulta-tipologias`, {
        method: "POST",
        headers: {
          "Content-Type": "application/json",
          Authorization: `Bearer ${token}`,
        },
        body: JSON.stringify({ fecha_inicio: fechaInicio, fecha_fin: fechaFin }),
      });
  
      if (!response.ok) {
        throw new Error(`Error al obtener datos: ${response.statusText}`);
      }
  
      const data = await response.json();
  
      if (!Array.isArray(data)) {
        throw new Error("La API no devolvió un arreglo válido.");
      }
  
      const workbook = XLSX.utils.book_new();
  
      // Crear hoja y mapear los datos en celdas específicas
      const worksheetData = data.map((item) => [
        item.TIPO_GESTION || "",
        item.TIPOLOGIA || "",
        item.SUBTIPOLOGIA || "",
        item.RAZON_MORA || "",
        item.TIPO_CONTACTO || "",
        item.OBSERVACIONES || "",
        item.INVESTIGACION || "",
        item.FECHA || "",
        item.USUARIO || "",
      ]);
  
      const headers = [
        "TIPO GESTION", "TIPOLOGIA", "SUBTIPOLOGIA", "RAZÓN DE MORA", "TIPO DE CONTACTO", "OBSERVACIONES", "INVESTIGACION", "FECHA", "USUARIO",
      ];
      worksheetData.unshift(headers);
      const worksheet = XLSX.utils.aoa_to_sheet(worksheetData);
  
      XLSX.utils.book_append_sheet(workbook, worksheet, "Reporte de tipologias");
  
      const excelData = XLSX.write(workbook, { bookType: "xlsx", type: "array" });
  
      const blob = new Blob([excelData], { type: "application/octet-stream" });
      const link = document.createElement("a");
      link.href = URL.createObjectURL(blob);
      link.download = `Reporte_tipologias_${fechaInicio}_to_${fechaFin}.xlsx`;
      link.click();
    } catch (error) {
      Swal.fire("Error", `No se pudo descargar la plantilla: ${error.message}`, "error");
    }
  };
  
  const handleBackToPanel = () => {
    const urlParams = getUrlParams();
    window.location.href = `./modulos?id=${urlParams.id}&campana=${urlParams.campana}`;
  };

  useEffect(() => {
    const today = new Date();
    const maxDate = today.toISOString().split("T")[0];
    today.setMonth(today.getMonth() - 2);
    const minDate = today.toISOString().split("T")[0];
  
    document.getElementById("fechaInicio").setAttribute("max", maxDate);
    document.getElementById("fechaInicio").setAttribute("min", minDate);
    document.getElementById("fechaFin").setAttribute("max", maxDate);
    document.getElementById("fechaFin").setAttribute("min", minDate);
  }, []);

  return (
    <div className="container mt-5">
      <div className="card">
        <div className="card-header text-center">
          <h4>Reporte Tipologías</h4>
          <button className="btn btn-warning" onClick={handleBackToPanel}>
            Regresar al panel de módulos
          </button>
        </div>
        <div className="card-body">
        <div className="mb-3">
  <label htmlFor="fechaInicio">Fecha de inicio:</label>
  <input
    id="fechaInicio"
    type="date"
    className="form-control"
    value={fechaInicio}
    onChange={(e) => setFechaInicio(e.target.value)}
  />
</div>
<div className="mb-3">
  <label htmlFor="fechaFin">Fecha de fin:</label>
  <input
    id="fechaFin"
    type="date"
    className="form-control"
    value={fechaFin}
    onChange={(e) => setFechaFin(e.target.value)}
  />
</div>
<div className="mb-3">
  <button className="btn btn-primary" onClick={handleDownloadTemplate}>
    Descargar Reporte
  </button>
</div>

          {loaderVisible && <div className="loader mt-3"></div>}
        </div>
      </div>
    </div>
  );
};

export default App;
